233:  public async listInbox(input: {
234:    readonly actorUserId: string;
235:    readonly providerId: string;
236:    readonly limit: number;
237:  }): Promise<{ readonly items: readonly InboxItem[]; readonly nextCursor: null }> {
238:    await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
239:    const db = clientOf(this.deps);
240:    const now = this.deps.now();
241:    const pending = await db.bookingResponse.findMany({
242:      where: {
243:        providerId: input.providerId,
244:        status: "PENDING",
245:        booking: { status: "CONFIRMED", providerId: input.providerId },
246:      },
247:      include: { booking: true },
248:      orderBy: { expiresAt: "asc" },
249:      take: 100,
250:    });
251:    const items: InboxItem[] = [];
252:    for (const row of pending) {
253:      if (row.expiresAt.getTime() <= now.getTime()) {
254:        await this.expireIfPending(row.bookingId);
255:        continue;
256:      }
257:      items.push({
258:        bookingId: row.bookingId,
259:        status: "CONFIRMED",
260:        startsAt: row.booking.startsAt.toISOString(),
261:        endsAt: row.booking.endsAt.toISOString(),
262:        responseStatus: "PENDING",
263:        expiresAt: row.expiresAt.toISOString(),
264:        version: row.booking.version,
265:      });
266:      if (items.length >= input.limit) break;
267:    }
268:    return { items, nextCursor: null };
269:  }
