586:  public async customerCancelConfirmed(input: {
587:    readonly customerUserId: string;
588:    readonly bookingId: string;
589:    readonly version: number;
590:    readonly reason: string;
591:    readonly command?: {
592:      readonly customerUserId: string;
593:      readonly commandType: "CANCEL";
594:      readonly idempotencyKey: string;
595:      readonly requestHash: string;
596:    };
597:    readonly responseJson?: Record<string, unknown>;
598:  }): Promise<{ readonly bookingId: string; readonly status: "CANCELLED" }> {
599:    const db = clientOf(this.deps);
600:    const owned = await db.booking.findFirst({
601:      where: { id: input.bookingId, customerUserId: input.customerUserId },
602:      select: { id: true },
603:    });
604:    failWhen(owned === null, () => bookingError("NOT_FOUND"));
605:    await this.expireIfPending(input.bookingId);
606:    return db.$transaction(async (tx) => {
607:      const booking = requirePresent(
608:        await tx.booking.findFirst({
609:          where: { id: input.bookingId, customerUserId: input.customerUserId },
610:        }),
611:        () => bookingError("NOT_FOUND"),
612:      );
613:      failWhen(!canCancelAfterConfirm(booking.status), () => bookingError("TRANSITION_NOT_AVAILABLE"));
614:      failWhen(booking.version !== input.version, () => bookingError("CONFLICT"));
615:      const reason = requirePresent(
616:        await tx.cancellationReason.findFirst({
617:          where: {
618:            code: customerCancelReasonCode(input.reason),
619:            actor: "CUSTOMER",
620:            purpose: "CANCEL",
621:            active: true,
622:          },
623:        }),
624:        () => bookingError("VALIDATION_FAILED", { reason: "UNKNOWN_REASON" }),
625:      );
626:      await this.requireRule(tx, "CUSTOMER", booking.status, "CANCELLED");
627:      const owner = requirePresent(
628:        await this.deps.resolveProviderOwnerUserId(booking.providerId),
629:        () => bookingError("DEPENDENCY_FAILURE", { reason: "PROVIDER_OWNER" }),
630:      );
631:      const commandRow = await this.reserveCustomerCommand(tx, input);
632:      await this.terminalCancel(tx, {
633:        bookingId: input.bookingId,
634:        expectedVersion: input.version,
635:        fromStatus: booking.status,
636:        actorKind: "CUSTOMER",
637:        actorUserId: input.customerUserId,
638:        actorType: "CUSTOMER",
639:        reasonId: reason.id,
640:        reasonCode: reason.code,
641:        notifyTemplate: "BOOKING_CANCELLED",
642:        recipientUserId: owner,
643:        locale: booking.locale,
644:      });
645:      if (commandRow !== null) {
646:        await tx.bookingCommand.update({
647:          where: { id: commandRow.id },
648:          data: {
649:            responseJson:
650:              input.responseJson ?? {
651:                id: input.bookingId,
652:                status: "CANCELLED",
653:                version: input.version + 1,
654:              },
655:          },
656:        });
657:      }
658:      return { bookingId: input.bookingId, status: "CANCELLED" as const };
659:    });
660:  }
