662:  private async reserveCustomerCommand(
663:    tx: BookingTx,
664:    input: {
665:      readonly bookingId: string;
666:      readonly command?: {
667:        readonly customerUserId: string;
668:        readonly commandType: "CANCEL";
669:        readonly idempotencyKey: string;
670:        readonly requestHash: string;
671:      };
672:    },
673:  ): Promise<{ readonly id: string } | null> {
674:    if (input.command === undefined) {
675:      return null;
676:    }
677:    try {
678:      return (await tx.bookingCommand.create({
679:        data: {
680:          customerUserId: input.command.customerUserId,
681:          commandType: input.command.commandType,
682:          idempotencyKey: input.command.idempotencyKey,
683:          bookingId: input.bookingId,
684:          requestHash: input.command.requestHash,
685:          responseJson: { reserved: true },
686:        },
687:      })) as { id: string };
688:    } catch (error) {
689:      if (isUniqueCollision(error)) {
690:        throw new BookingIdempotencyCollision();
691:      }
692:      throw error;
693:    }
694:  }
