696:  public async ensurePendingResponse(
697:    tx: BookingTx,
698:    input: {
699:      readonly bookingId: string;
700:      readonly providerId: string;
701:      readonly countryId: string;
702:      readonly customerUserId: string;
703:      readonly locale: "AR" | "EN";
704:    },
705:  ): Promise<void> {
706:    const hours = requirePresent(
707:      await this.deps.readResponseHours(input.countryId),
708:      () => bookingError("DEPENDENCY_FAILURE", { reason: "PROVIDER_RESPONSE_HOURS" }),
709:    );
710:    const existing = await tx.bookingResponse.findUnique({
711:      where: { bookingId: input.bookingId },
712:    });
713:    if (existing !== null) {
714:      return;
715:    } else {
716:    const ownerUserId = requirePresent(
717:      await this.deps.resolveProviderOwnerUserId(input.providerId),
718:      () => bookingError("DEPENDENCY_FAILURE", { reason: "PROVIDER_OWNER" }),
719:    );
720:    const expiresAt = new Date(this.deps.now().getTime() + hours * 60 * 60 * 1000);
721:    await tx.bookingResponse.create({
722:      data: {
723:        bookingId: input.bookingId,
724:        providerId: input.providerId,
725:        status: "PENDING",
726:        expiresAt,
727:      },
728:    });
729:    await this.insertIntent(tx, {
730:      bookingId: input.bookingId,
731:      template: "BOOKING_CONFIRMED_FOR_PROVIDER",
732:      recipientUserId: ownerUserId,
733:      locale: input.locale,
734:      idempotencyKey: shaIdempotency([
735:        "BOOKING_CONFIRMED_FOR_PROVIDER",
736:        input.bookingId,
737:      ]),
738:    });
739:    }
740:  }
