742:  private async expireIfPending(bookingId: string): Promise<void> {
743:    const run = async (db: BookingTx) => {
744:      const response = await db.bookingResponse.findUnique({
745:        where: { bookingId },
746:        include: { booking: true },
747:      });
748:      if (!isPendingResponse(response)) {
749:        return;
750:      } else if (response.expiresAt.getTime() > this.deps.now().getTime()) {

751:        return;
752:      } else if (response.booking.status !== "CONFIRMED") {
753:        return;
754:      } else {
755:      const reason = requirePresent(
756:        await db.cancellationReason.findUnique({
757:          where: { code: "PROVIDER_RESPONSE_EXPIRED" },
758:        }),
759:        () => bookingError("DEPENDENCY_FAILURE", { reason: "EXPIRY_REASON" }),
760:      );
761:      await this.requireRule(db, "SYSTEM", "CONFIRMED", "CANCELLED");
762:      await this.terminalCancel(db, {
763:        bookingId,
764:        expectedVersion: response.booking.version,
765:        fromStatus: "CONFIRMED",
766:        actorKind: "SYSTEM",
767:        actorUserId: null,
768:        actorType: "SYSTEM",
769:        reasonId: reason.id,
770:        reasonCode: reason.code,
771:        responseStatus: "EXPIRED",
772:        notifyTemplate: "BOOKING_RESPONSE_EXPIRED",
773:        recipientUserId: response.booking.customerUserId,
774:        locale: response.booking.locale,
775:      });
776:      }
777:    };
778:    try {
779:      await clientOf(this.deps).$transaction((nested) => run(nested));
780:    } catch (error) {
781:      if (isConflictError(error)) {
782:        return;
783:      } else {
784:        throw error;
785:      }
786:    }
787:  }
