789:  private async terminalCancel(
790:    tx: BookingTx,
791:    input: {
792:      readonly bookingId: string;
793:      readonly expectedVersion: number;
794:      readonly fromStatus: string;
795:      readonly actorKind: "CUSTOMER" | "PROVIDER" | "STAFF_ADMIN" | "SYSTEM";
796:      readonly actorUserId: string | null;
797:      readonly actorType: "CUSTOMER" | "PROVIDER" | "STAFF_ADMIN" | "SYSTEM";
798:      readonly reasonId: string;
799:      readonly reasonCode: string;
800:      readonly responseStatus?: "REJECTED" | "EXPIRED";
801:      readonly notifyTemplate: "BOOKING_REJECTED" | "BOOKING_RESPONSE_EXPIRED" | "BOOKING_CANCELLED";
802:      readonly recipientUserId: string;
803:      readonly locale: "AR" | "EN";
804:    },
805:  ): Promise<string> {
806:    const claimed = await tx.booking.updateMany({
807:      where: {
808:        id: input.bookingId,
809:        status: input.fromStatus as BookingStatusName,
810:        version: input.expectedVersion,
811:      },
812:      data: {
813:        status: "CANCELLED",
814:        version: { increment: 1 },
815:        cancelledAt: this.deps.now(),
816:      },
817:    });
818:    failWhen(claimed.count !== 1, () => bookingError("CONFLICT"));
819:    if (input.responseStatus !== undefined) {
820:      await tx.bookingResponse.updateMany({
821:        where: { bookingId: input.bookingId, status: "PENDING" },
822:        data: {
823:          status: input.responseStatus,
824:          decidedAt: this.deps.now(),
825:          decidedByUserId: input.actorUserId,
826:          ...(input.responseStatus === "REJECTED" ? { rejectReasonId: input.reasonId } : {}),
827:        },
828:      });
829:    } else {
830:      // Customer and provider-accepted cancels keep the response row unchanged.
831:    }
832:    const cancellation = await tx.bookingCancellation.create({
833:      data: {
834:        bookingId: input.bookingId,
835:        actorKind: input.actorKind,
836:        actorUserId: input.actorUserId,
837:        reasonId: input.reasonId,
838:        fromStatus: input.fromStatus,
839:      },
840:    });
841:    await tx.bookingStatusHistory.create({
842:      data: {
843:        bookingId: input.bookingId,
844:        fromStatus: input.fromStatus,
845:        toStatus: "CANCELLED",
846:        actorUserId: input.actorUserId,
847:        actorType: input.actorType,
848:        reasonCode: input.reasonCode,
849:      },
850:    });
851:    await this.insertIntent(tx, {
852:      bookingId: input.bookingId,
853:      template: input.notifyTemplate,
854:      recipientUserId: input.recipientUserId,
855:      locale: input.locale,
856:      idempotencyKey: shaIdempotency([input.notifyTemplate, input.bookingId]),
857:    });
858:    return cancellation.id;
859:  }
