765:  private mapAnswers(
766:    catalog: SnapshotReadyCatalogServiceDefinition,
767:    answers: readonly { readonly fieldId: string; readonly value: unknown }[],
768:  ): BookingAnswerRecord[] {
769:    const fields = new Map(catalog.fields.map((field) => [field.id, field]));
770:    const mapped: BookingAnswerRecord[] = [];
771:    const seen = new Set<string>();
772:    for (const answer of answers) {
773:      if (seen.has(answer.fieldId)) {
774:        throw bookingError("VALIDATION_FAILED", {
775:          field: "answers",
776:          fieldId: answer.fieldId,
777:          reason: "DUPLICATE_FIELD",
778:        });
779:      }
780:      seen.add(answer.fieldId);
781:      const field = fields.get(answer.fieldId);
782:      if (field === undefined || field.kind === "INFORMATION") {
783:        throw bookingError("VALIDATION_FAILED", {
784:          field: "answers",
785:          fieldId: answer.fieldId,
786:        });
787:      }
788:      try {
789:        mapped.push({
790:          fieldId: field.id,
791:          fieldCode: field.code,
792:          kind: field.kind,
793:          value: canonicalizeBookingAnswer(field, answer.value),
794:        });
795:      } catch (error) {
796:        if (error instanceof BookingAnswerValidationError) {
797:          throw bookingError("VALIDATION_FAILED", {
798:            field: "answers",
799:            fieldId: error.fieldId,
800:          });
801:        }
802:        throw error;
803:      }
804:    }
805:    return mapped;
806:  }
