546:  private async withIdempotency(input: {
547:    readonly customerUserId: string;
548:    readonly commandType:
549:      "CREATE" | "SUBMIT_FOR_DEPOSIT" | "CANCEL" | "ATTACH_MEDIA";
550:    readonly idempotencyKey: string;
551:    readonly request: unknown;
552:    readonly run: () => Promise<BookingAggregate>;
553:  }): Promise<unknown> {
554:    const requestHash = hashBookingRequest(input.request);
555:    const existing = await this.deps.repository.findCommand({
556:      customerUserId: input.customerUserId,
557:      commandType: input.commandType,
558:      idempotencyKey: input.idempotencyKey,
559:    });
560:    if (existing !== null) {
561:      if (existing.requestHash !== requestHash) {
562:        throw bookingError("CONFLICT", { reason: "IDEMPOTENCY_BODY_MISMATCH" });
563:      }
564:      return this.replayCompletedCommand(existing, input.customerUserId);
565:    }
566:    try {
567:      return this.present(await input.run());
568:    } catch (error) {
569:      if (error instanceof BookingTransitionUnavailable) {
570:        throw bookingError("TRANSITION_NOT_AVAILABLE");
571:      }
572:      if (error instanceof BookingIdempotencyCollision) {
573:        const raced = await this.deps.repository.findCommand({
574:          customerUserId: input.customerUserId,
575:          commandType: input.commandType,
576:          idempotencyKey: input.idempotencyKey,
577:        });
578:        if (raced === null || raced.requestHash !== requestHash) {
579:          throw bookingError("CONFLICT", {
580:            reason: "IDEMPOTENCY_BODY_MISMATCH",
581:          });
582:        }
583:        return this.replayCompletedCommand(raced, input.customerUserId);
584:      }
585:      throw error;
586:    }
587:  }
