946:    readonly commandType: "ACCEPT" | "REJECT" | "PROVIDER_CANCEL" | "STAFF_CANCEL";
947:    readonly idempotencyKey: string;
948:    readonly bookingId: string;
949:    readonly request: unknown;
950:    readonly run: (tx: BookingTx) => Promise<T>;
951:  }): Promise<T> {
952:    const db = clientOf(this.deps);
953:    const requestHash = requestHashOf(input.request);
954:    const existing = await db.bookingActorCommand.findUnique({
955:      where: {
956:        actorUserId_commandType_idempotencyKey: {
957:          actorUserId: input.actorUserId,
958:          commandType: input.commandType,
959:          idempotencyKey: input.idempotencyKey,
960:        },
961:      },
962:    });
963:    if (existing !== null) {
964:      failWhen(existing.requestHash !== requestHash, () => bookingError("IDEMPOTENCY_BODY_MISMATCH"));
965:      return existing.responseJson as T;
966:    } else {
967:    return db.$transaction(async (tx) => {
968:      const created = await tx.bookingActorCommand.create({
969:        data: {
970:          actorUserId: input.actorUserId,
971:          commandType: input.commandType,
972:          idempotencyKey: input.idempotencyKey,
973:          bookingId: input.bookingId,
974:          requestHash,
975:          responseJson: {},
976:        },
977:      });
978:      const result = await input.run(tx);
979:      await tx.bookingActorCommand.update({
980:        where: { id: created.id },
981:        data: { responseJson: result },
982:      });
983:      return result;
984:    });
985:    }
986:  }
